import {parsePairingCode,dispatchCall,sealDispatch} from './dispatch.js?v=0.15.0';
import {openTicketScanner} from './scanner-ui.js?v=0.15.0';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='delivery-manager-manager-v1';let config;try{config=JSON.parse(localStorage.getItem(key)||'null');}catch{}let draft,packet;try{draft=JSON.parse(localStorage.getItem('dm-manager-draft-'+config?.id)||'[]');packet=JSON.parse(localStorage.getItem('dm-manager-outbox-'+config?.id)||'null');}catch{draft=[];}let draftKind=localStorage.getItem('dm-manager-kind-'+config?.id)||'single';let error='',sending=false,statuses=[];
const persist=()=>{localStorage.setItem('dm-manager-kind-'+config.id,draftKind);localStorage.setItem('dm-manager-draft-'+config.id,JSON.stringify(draft));packet?localStorage.setItem('dm-manager-outbox-'+config.id,JSON.stringify(packet)):localStorage.removeItem('dm-manager-outbox-'+config.id);};
function render(){$('#manager').innerHTML=`<header class="manager-brand"><img src="icon.svg" alt=""><div><h1>Mike’s Dispatch</h1><p>Add orders. Send them to your driver.</p></div></header>${config?`<div class="${config.mode==='test'?'demo-banner':'hint'}"><strong>${config.mode==='test'?'TEST DISPATCH — fictional orders only':'LIVE DISPATCH — real driver records'}</strong></div><section class="card"><h2>Build an addition</h2><p>Every order sent together gets the same color on the driver’s phone. Order below is the requested stop order; due-soon scheduled orders can move first.</p>${draft.map((d,i)=>`<div class="manager-stop"><div><strong>${i+1}. ${esc(d.name||'Delivery')}</strong><p>${esc(d.address)}</p>${d.scheduledAt?'<span class="badge scheduled">Scheduled</span>':''}</div><div>${!packet?`<button data-edit="${i}">Edit</button><button data-up="${i}" ${i===0?'disabled':''}>↑</button><button data-down="${i}" ${i===draft.length-1?'disabled':''}>↓</button><button data-remove="${i}">Remove</button>`:''}</div></div>`).join('')}<div class="actions"><button id="add" class="primary" ${packet||draft.length>=12?'disabled':''}>+ Add order</button></div><label for="send-kind">Send these orders as</label><select id="send-kind" ${packet?'disabled':''}><option value="single">${draft.length>1?'Separate single deliveries':'Single delivery'}</option><option value="batch">One batch</option></select><p class="muted">One send = one addition. Orders appear as pending and never start a run automatically. Only additions are supported; contact the driver directly for corrections or cancellations.</p><button id="send" class="primary" ${sending||(!draft.length&&!packet)?'disabled':''}>${sending?'Sending…':packet?'Retry same addition':'Send addition to driver'}</button>${packet?'<p class="hint">A send is awaiting confirmation. Retry uses the same ID to prevent duplicates; editing is locked until it is resolved.</p>':''}</section><section class="card"><div class="row"><h2>Recent sends</h2><button id="refresh">Refresh status</button></div><p class="muted">Received means saved on the driver’s phone. Queued means awaiting collection; it expires after 24 hours.</p>${statuses.map(x=>`<p>${new Date(x.created_at).toLocaleString()} · <strong>${esc(x.status)}</strong></p>`).join('')||'<p>No sends checked yet.</p>'}</section><button id="unpair">Use a different pairing</button><p class="muted">Order details are encrypted on this device before upload. The server deletes the encrypted copy after receipt or expiry. This phone keeps unsent drafts locally. Keep the pairing code private.</p>`:`<section class="card"><h2>Connect to a driver</h2><p>On the driver’s app, open Settings → Mike’s dispatch. Create a test or live pairing and paste its private code here.</p><form id="pair-form"><label for="pair-code">Pairing code</label><textarea id="pair-code" required autocomplete="off" autocapitalize="off" spellcheck="false"></textarea><button class="primary">Connect manager</button></form></section>`}<p class="error" role="alert">${esc(error)}</p>`;
 if(!config){$('#pair-form').onsubmit=async e=>{e.preventDefault();try{const c=parsePairingCode($('#pair-code').value.trim());await dispatchCall('status',{},c.token);config=c;localStorage.setItem(key,JSON.stringify(c));draft=JSON.parse(localStorage.getItem('dm-manager-draft-'+c.id)||'[]');packet=JSON.parse(localStorage.getItem('dm-manager-outbox-'+c.id)||'null');draftKind=localStorage.getItem('dm-manager-kind-'+c.id)||'single';error='';render();}catch(e){error=e.message;render();}};return;}
 $('#send-kind').value=draftKind;$('#send-kind').onchange=()=>{draftKind=$('#send-kind').value;persist();};$('#add').onclick=()=>orderForm();$('#send').onclick=send;$('#refresh').onclick=refresh;$('#unpair').onclick=()=>{if(draft.length||packet)return fail('Finish or remove the current draft before changing pairing.');localStorage.removeItem(key);config=null;statuses=[];render();};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>orderForm(Number(b.dataset.edit)));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{draft.splice(Number(b.dataset.remove),1);persist();render();});document.querySelectorAll('[data-up],[data-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.up??b.dataset.down),j=b.dataset.up!=null?i-1:i+1;[draft[i],draft[j]]=[draft[j],draft[i]];persist();render();});}
function fail(text){error=text;render();}
async function refresh(){try{statuses=(await dispatchCall('status',{},config.token)).packets;error='';render();}catch(e){fail(e.message);}}
async function send(){if(sending)return;sending=true;const kind=$('#send-kind').value;try{if(!packet){packet=await sealDispatch(config,{version:1,mode:config.mode,kind,orders:draft});persist();}render();await dispatchCall('send',packet,config.token);packet=null;draft=[];draftKind='single';persist();error='';sending=false;await refresh();}catch(e){sending=false;fail(e.message);}}
function orderForm(index){if(packet)return;const d=draft[index]||{},modal=document.createElement('dialog');document.body.append(modal);modal.innerHTML=`<form><h2>${index==null?'Add order':'Edit order'}</h2><button id="manager-scan" type="button" class="primary">Scan ticket</button><p class="muted">Scanner setup uses the restaurant’s driver setup code once. Review the result before saving.</p><label>Customer name<input name="name" autocapitalize="words" value="${esc(d.name)}"></label><label>Customer phone<input name="phone" type="tel" inputmode="tel" value="${esc(d.phone)}"></label><label>Delivery address and unit<input name="address" required value="${esc(d.address)}" placeholder="Seattle street address and unit"></label><label>Ticket number<input name="ticket" inputmode="numeric" value="${esc(d.ticket)}"></label><label>Drinks or ice cream? (required)<select name="cold" required><option value="">Choose yes or no</option><option value="yes" ${d.hasColdItems===true?'selected':''}>Yes</option><option value="no" ${d.hasColdItems===false?'selected':''}>No</option></select></label><label>Which drinks / ice cream?<input name="coldItemDetails" value="${esc(d.coldItemDetails)}"></label><label>Alcohol? (required)<select name="alcohol" required><option value="">Choose yes or no</option><option value="yes" ${d.hasAlcohol===true?'selected':''}>Yes — bring a signature receipt</option><option value="no" ${d.hasAlcohol===false?'selected':''}>No</option></select></label><label class="checkbox-label"><input name="signature" type="checkbox" ${d.needsSignature?'checked':''}> Needs signature</label><label>Scheduled arrival (optional)<input name="scheduledAt" type="datetime-local" value="${esc(d.scheduledLocal)}"></label><label>Notes<textarea name="notes">${esc(d.notes)}</textarea></label><p class="error" role="alert"></p><div class="actions"><button id="cancel-order" type="button">Cancel</button><button class="primary">Save order</button></div></form>`;modal.showModal();const close=()=>{modal.close();modal.remove();};modal.querySelector('#cancel-order').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});modal.querySelector('#manager-scan').onclick=()=>openTicketScanner(result=>{for(const k of ['name','phone','address','ticket'])if(result.fields?.[k]||result[k])modal.querySelector(`[name=${k}]`).value=result.fields?.[k]||result[k];});modal.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),cold=f.get('cold')==='yes';if(cold&&!f.get('coldItemDetails').trim()){modal.querySelector('.error').textContent='List the drinks or ice cream.';return;}const value={name:f.get('name').trim(),phone:f.get('phone').trim(),address:f.get('address').trim(),ticket:f.get('ticket').trim(),hasColdItems:cold,coldItemDetails:f.get('coldItemDetails').trim(),hasAlcohol:f.get('alcohol')==='yes',needsSignature:!!f.get('signature'),notes:f.get('notes').trim(),scheduledLocal:f.get('scheduledAt'),scheduledAt:f.get('scheduledAt')?new Date(f.get('scheduledAt')).toISOString():null};if(index==null)draft.push(value);else draft[index]=value;persist();close();render();};}
render();
